import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.Ky-Ipuyb.js";const m=JSON.parse('{"title":"RmlUi ソース構成","description":"","frontmatter":{"lang":"ja","sourcePath":"docs/rmlui/source-layout.ja.md"},"headers":[],"relativePath":"ja/rmlui/source-layout.md","filePath":"ja/rmlui/source-layout.md"}'),r={name:"ja/rmlui/source-layout.md"};function a(s,t,i,n,l,p){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="rmlui-ソース構成" tabindex="-1">RmlUi ソース構成 <a class="header-anchor" href="#rmlui-ソース構成" aria-label="Permalink to &quot;RmlUi ソース構成&quot;">​</a></h1><p><code>packages/sfml.js-rmlui</code> はネイティブバインディング、TypeScript インターフェース、テストを責務別に配置しています。新しい実装は担当モジュールに置き、関連するヘッダーと実装ファイルをまとめます。</p><table tabindex="0"><thead><tr><th>ディレクトリ</th><th>責務</th></tr></thead><tbody><tr><td><code>runtime/</code></td><td>初期化、Context、実行時状態、機能照会、コールバック寿命、Plugin、Debugger</td></tr><tr><td><code>dom/documents/</code></td><td>ドキュメント、Factory、属性集合、XML 解析</td></tr><tr><td><code>dom/elements/</code></td><td>Element、レイアウト、スクロール、要素のインスタンス化、SVG、Lottie</td></tr><tr><td><code>dom/controls/</code></td><td>フォーム、テキストコントロール、選択肢、パネル</td></tr><tr><td><code>data/</code></td><td>データモデル、型登録、アドレス、メンバー、バッチ処理、診断</td></tr><tr><td><code>events/</code></td><td>イベント、リスナー、ディスパッチ、インスタンス化</td></tr><tr><td><code>style/properties/</code></td><td>Property、パーサー、仕様、スタイルシート</td></tr><tr><td><code>style/effects/</code></td><td>デコレーター、フィルター、エフェクト値とコールバック</td></tr><tr><td><code>style/values/</code></td><td>計算済みスタイル、スタイル構造体、変換、マップされたビュー</td></tr><tr><td><code>animation/</code></td><td>アニメーション、トランジション、Tween、値コールバック</td></tr><tr><td><code>rendering/</code></td><td>描画管理、ジオメトリ、テクスチャ、レイヤー、リソース、SFML 描画アダプター</td></tr><tr><td><code>fonts/</code></td><td>フォント読み込み、FreeType/HarfBuzz/ビットマップエンジン、計測、グリフ、フォントエフェクト</td></tr><tr><td><code>scripting/</code></td><td>スクリプトインターフェース、ホスト、スクリプトオブジェクト</td></tr><tr><td><code>scripting/lua/</code></td><td>Lua ホスト、モデル、値、関数、インスタンス化</td></tr><tr><td><code>platform/</code></td><td>SFML システム連携、入力、テキスト入力、ウィンドウ密度</td></tr><tr><td><code>io/</code></td><td>ファイルインターフェース、ストリーム</td></tr><tr><td><code>values/</code></td><td>Variant、数値、文字列、URL、共有型</td></tr></tbody></table><p>これらは <code>native/</code> と <code>src/</code> の下にあります。片方の層だけで必要な実装はその層に置きます。<code>src/internal/</code> はネイティブローダー、ラッパー割り当て、共有メモリ変換など、モジュール間の内部プロトコルを保持します。</p><p><code>src/index.ts</code> が npm の公開入口、<code>native/addon.cc</code> がネイティブモジュールの登録入口です。パッケージのビルド設定はルートの <code>binding.gyp</code>、<code>package.json</code>、<code>tsconfig.json</code> に残します。</p><p>生成ファイルは <code>src/generated/</code> と <code>native/generated/</code> にあります。生成処理の変更は <code>tools/codegen/</code> の生成器を編集してから再生成します。</p><table tabindex="0"><thead><tr><th>ツールディレクトリ</th><th>責務</th></tr></thead><tbody><tr><td><code>tools/build/</code></td><td>パッケージのネイティブビルド、Lua の C++ コンパイル、コンパイルデータベース修正。リポジトリ LSP データベースの統合は所属する Rush ワークスペース内だけで実行</td></tr><tr><td><code>tools/codegen/</code></td><td>上流ヘッダーから入力、イベント、プロパティ ID、スタイルバインディングを生成</td></tr><tr><td><code>tools/dependencies/</code></td><td>依存バージョン、検証、ダウンロード、ビルドソース一覧</td></tr><tr><td><code>tools/dependencies/patches/</code></td><td>RmlUi、Lua、Debugger、数値、文字列、rlottie のパッチ</td></tr><tr><td><code>tools/performance/</code></td><td>性能測定、ネイティブ呼び出し回数</td></tr><tr><td><code>tools/testing/</code></td><td>実行時テストの再帰収集・実行、クリップボード保護、npm ソースパッケージのファイル一覧とビルド依存の検証</td></tr></tbody></table><p><code>test/</code> は実行時・型テストをモジュール別に配置します。<code>test/native/</code> は C++ 対照プログラムとビルドスクリプトをモジュール別に配置します。スクリプトは現在のパッケージのオブジェクトファイルを再利用し、呼び出し元が既存の一時出力ディレクトリを指定します。</p><p><code>packages/sfmljs-rmlui-vscode/tools/testing/</code> は既存の VS Code で拡張機能の統合検証を実行します。同パッケージの <code>tools/packaging/</code> は VSIX 内蔵クライアント、言語サーバー、言語リソース、四言語の README を検証します。リポジトリ共通の Windows ツールチェーン初期化は <code>tools/ci/</code> にあり、既存の Node.js CI と専用 RmlUi CI で共有します。</p><p><code>third_party/</code> は上流のディレクトリ構成を保持します。<code>build/</code> と <code>dist/</code> は既存のビルドディレクトリを再利用します。ソース移動後は、新しいパスの成果物が存在する旧成果物だけを削除します。</p><p>ディレクトリ移動は RmlUi 6.3 全体の受け入れ完了を意味しません。<code>audit/6.3/</code> の既存証拠は採取時のパスとハッシュを保持します。過去のパスは<a href="https://github.com/XadillaX/node-sfml/blob/main/docs/rmlui/audit/6.3/source-layout-map.json" target="_blank" rel="noreferrer">移動対応表</a>で確認してください。</p>',11)])])}const g=d(r,[["render",a]]);export{m as __pageData,g as default};
